// `new WeakRef` has no scriptc lowering: `weak` must compile to a function
// that throws when called, while `ok` stays static. (dist/index.js throws an
// Error in `weak` too, so Node and the native build agree.)
export function ok(): string {
  return "ok";
}

export function weak(): string {
  const ref = new WeakRef({ a: 1 });
  return typeof ref.deref();
}

export class Holder {
  value = 1;
  get(): number {
    return this.value;
  }
  weak(): string {
    return typeof new WeakRef({ b: 2 }).deref();
  }
}
